window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[44]={"id":"044","numero":44,"titre":"Tuméfaction pelvienne chez la femme","objectifs":[{"id":"44-1","rang":"A","rubrique":"Étiologies","titre":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","contenu":"<p>Devant toute <span class=\"kw-clinique\">tuméfaction</span> pelvienne chez une femme en âge de procréer, le <strong>premier réflexe</strong> est d’<strong>éliminer une <span class=\"kw-ci\">grossesse</span></strong> par dosage de <span class=\"kw-bio\">β-hCG</span> (un <strong>utérus gravide</strong> est <em>augmenté de volume et mou</em> dans un contexte de retard de règles).</p>\n\n      <p>Une fois la <span class=\"kw-ci\">grossesse</span> écartée, les <strong>2 étiologies les plus fréquentes</strong> sont :</p>\n\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Origine</th><th>Repère clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fibrome utérin</strong></td>\n            <td>Utérine</td>\n            <td>Tumeur utérine <strong>la plus fréquente</strong> · <span class=\"kw-clinique\">masse</span> <span class=\"kw-clinique\">dépendante de l’utérus</span> au <span class=\"kw-alerte\">TV</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Kyste de l’ovaire</span></strong></td>\n            <td>Ovarienne</td>\n            <td><span class=\"kw-clinique\">Masse</span> <span class=\"kw-clinique\">latéro-utérine indépendante</span> de l’utérus · ± complications (torsion, hémorragie, <span class=\"kw-alerte\">rupture</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span class=\"kw-bio\">β-hCG</span> systématique → puis <strong>fibrome utérin</strong> et <strong>kyste ovarien</strong> en tête. L’<span class=\"kw-imagerie\">échographie pelvienne</span> est l’examen clé pour les départager (cf. obj-10).\n      </div>","frequence":0},{"id":"44-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les autres causes de tuméfaction pelvienne","contenu":"<p>Au-delà de la <span class=\"kw-ci\">grossesse</span>, du fibrome et du kyste ovarien, les autres causes se classent <strong>par organe</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Origine</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Utérine</strong></td>\n            <td>\n              · <strong><span class=\"kw-etio\">Sarcome / léiomyosarcome</span></strong> : rare, surtout après la ménopause, <span class=\"kw-clinique\">masse</span> à <span class=\"kw-alerte\">progression rapide</span><br>\n              · <strong><span class=\"kw-etio\">Adénomyose</span></strong> : rarement (utérus ne dépasse pas le double de sa taille)<br>\n              · <strong><span class=\"kw-etio\">Cancer de l’endomètre</span></strong> : exceptionnellement (surtout si tumeur endocavitaire avec sténose du col → <span class=\"kw-alerte\">hématométrie</span> ± pyométrie)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ovarienne</strong></td>\n            <td>· <strong><span class=\"kw-etio\">Abcès ovarien</span></strong> (post-pelvipéritonite, <span class=\"kw-ttt\">ponction</span>)<br>· <strong><span class=\"kw-etio\">Endométriome</span></strong><br>· <span class=\"kw-alerte\">Cancer de l’ovaire</span> (rare avant la ménopause)</td>\n          </tr>\n          <tr>\n            <td><strong>Tubaire</strong></td>\n            <td>· <strong><span class=\"kw-etio\">Hydrosalpinx</span></strong> · bloc adhérentiel post-<span class=\"kw-etio\">infectieux</span> · kyste paratubaire / vestigial<br><em>(la trompe se dilate rarement assez pour donner une <span class=\"kw-clinique\">masse</span> — souvent masse annexielle infectieuse mixte trompe + ovaire)</em></td>\n          </tr>\n          <tr>\n            <td><strong>Péritonéale</strong></td>\n            <td>Endométriose du cul-de-sac recto-utérin → plutôt <em>induration / <span class=\"kw-clinique\">nodule</span></em> qu’une vraie <span class=\"kw-clinique\">masse</span></td>\n          </tr>\n          <tr>\n            <td><strong>Digestive</strong> (rares)</td>\n            <td>Sigmoïdite · <span class=\"kw-alerte\">cancer colo-rectal</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Une <span class=\"kw-clinique\">masse</span> pelvienne <em>irrégulière, fixée, à progression rapide</em>, surtout <strong>après la ménopause</strong> ou avec <span class=\"kw-clinique\">ascite</span>, fait évoquer une <span class=\"kw-alerte\">tumeur maligne</span> (ovaire, sarcome, endomètre) jusqu’à preuve du contraire.\n      </div>","frequence":2},{"id":"44-3","rang":"B","rubrique":"Epidémiologie","titre":"Fréquence des fibromes et des kystes ovariens bénins","contenu":"<h4>Fibrome utérin</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span></strong></td>\n            <td>Augmente avec l’âge : <span class=\"kw-chiffre\">20–30 %</span> des femmes après <span class=\"kw-chiffre\">35 ans</span> · <span class=\"kw-chiffre\">50 %</span> à<span class=\"kw-chiffre\"> 50 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span> spontanée</strong></td>\n            <td>Imprévisible · <strong>régression habituelle après la ménopause</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Kystes ovariens bénins</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Très fréquents pendant la <strong>période d’activité génitale</strong> · l’immense majorité sont des <strong>kystes fonctionnels</strong> bénins</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>La plupart <strong>régressent spontanément</strong> (contrôle échographique à <span class=\"kw-chiffre\">3 mois</span>) · la persistance &gt; <span class=\"kw-chiffre\">3 mois</span> fait évoquer un kyste <strong>organique</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Bénin <span class=\"kw-bio\">vs</span> malin</strong></td>\n            <td>Les tumeurs <span class=\"kw-alerte\">malignes</span> de l’ovaire restent <strong>rares avant la ménopause</strong> · l’épithélial représente <span class=\"kw-chiffre\">~ 90 %</span> des tumeurs organiques (cf. item 306)</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"44-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","contenu":"<p><span class=\"kw-chiffre\">~ 50 %</span> des fibromes sont <strong>asymptomatiques</strong>, découverts fortuitement à l’examen ou en imagerie. Quand ils s’expriment, trois grands tableaux dominent.</p>\n\n      <h4>1 · Saignements utérins anormaux — signe le plus fréquent</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Ménorragies</span></strong> (souvent polyménorrhée) : règles <span class=\"kw-chiffre\">&gt; 6 jours</span> et/ou <span class=\"kw-chiffre\">&gt; 80 mL</span></li>\n        <li><strong><span class=\"kw-clinique\">Métrorragies</span></strong> : rares isolées, plutôt <em>ménométrorragies</em></li>\n        <li><strong><span class=\"kw-def\">Score de Higham</span> &gt; 100</strong> = ménorragies (nombre de changes + caillots)</li>\n        <li>Complication : <span class=\"kw-alerte\">anémie ferriprive</span>, parfois profonde</li>\n      </ul>\n\n      <p><em>Quels fibromes saignent le plus ?</em></p>\n      <ul>\n        <li><strong>Sous-muqueux (FIGO 0–2)</strong> : <em>le plus souvent</em>, action directe sur la muqueuse endométriale</li>\n        <li><strong>Interstitiels (FIGO 3–4)</strong> : <em>plus rarement</em>, altération de la contractilité du myomètre</li>\n        <li><strong>Sous-séreux (FIGO 5–7)</strong> : <em>rarement</em> à l’origine d’hémorragies</li>\n      </ul>\n\n      <h4>2 · Syndrome de <span class=\"kw-clinique\">masse</span> pelvienne</h4>\n\n      <p>Apparition <strong>progressive</strong>, sans douleur vraie : <span class=\"kw-clinique\">pesanteur</span> pelvienne, <span class=\"kw-clinique\">masse</span> abdominale, augmentation du volume de l’abdomen.</p>\n\n      <p>Complications par <strong>compression d’organes de voisinage</strong> :</p>\n      <ul>\n        <li><strong>Vésicale</strong> : <span class=\"kw-clinique\">pollakiurie</span> par irritation, rétention d’urines</li>\n        <li><strong>Urétérale</strong> : urétéro-hydronéphrose, coliques néphrétiques, pyélonéphrites</li>\n        <li><strong>Digestive</strong> : <span class=\"kw-clinique\">constipation</span>, faux besoins par compression rectale</li>\n        <li><strong>Veineuse pelvienne</strong> : <span class=\"kw-clinique\">œdèmes des membres inférieurs</span>, <span class=\"kw-alerte\">TVP</span></li>\n        <li><strong>Nerveuse</strong> : sciatalgie (face postérieure cuisse), névralgie obturatrice (face interne cuisse)</li>\n      </ul>\n\n      <p><em>Fibromes à risque de <span class=\"kw-clinique\">masse</span> pelvienne :</em> volumineux <span class=\"kw-chiffre\">&gt; 5 cm</span> · sous-séreux (FIGO 5–7).</p>\n\n      <h4>3 · Dysménorrhée</h4>\n\n      <p>Possible si <strong>fibrome du col ou de l’isthme</strong> (FIGO 8) — gêne l’évacuation du flux menstruel.</p>\n\n      <h4>Examen clinique — <span class=\"kw-alerte\">TV</span></h4>\n\n      <ul>\n        <li>Fibromes palpables = souvent <strong>interstitiels (3–4)</strong> ou <strong>sous-séreux (5–7)</strong></li>\n        <li><strong>Utérus augmenté de volume</strong> : fibromes interstitiels ou sous-séreux</li>\n        <li><strong><span class=\"kw-clinique\">Masse</span> latéro-utérine dépendante de l’utérus</strong> : fibrome sous-séreux sessile</li>\n        <li><strong><span class=\"kw-clinique\">Masse</span> latéro-utérine indépendante</strong> : fibrome pédiculé</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Devant des <em>ménométrorragies + utérus polymyomateux palpable au <span class=\"kw-alerte\">TV</span></em>, doser <strong><span class=\"kw-bio\">NFS</span> (anémie ferriprive) + <span class=\"kw-bio\">ferritine</span></strong>, faire une <strong><span class=\"kw-imagerie\">échographie</span> pelvienne</strong> et apprécier le <span class=\"kw-def\">score</span> de Higham.\n      </div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/uterine-leiomyoma","label":"Radiopaedia : Uterine leiomyoma"},{"href":"https://radiopaedia.org/articles/figo-classification-system-foruterine-leiomyoma","label":"Radiopaedia : Classification FIGO des fibromes utérins"}]},{"id":"44-5","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications des fibromes","contenu":"<h4>Complications douloureuses aiguës</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-etio\">Nécrobiose aseptique</span></strong> = principale cause de douleur du fibrome</li>\n        <li><strong>Torsion</strong> d’un fibrome sous-séreux pédiculé (FIGO 7, plus rare)</li>\n        <li><strong>Accouchement par le col</strong> d’un fibrome pédiculé sous-muqueux avec coliques expulsives (plus rare)</li>\n      </ul>\n\n      <h4><span class=\"kw-etio\">Nécrobiose aseptique</span> de fibrome — tableau clinique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Caractéristique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td><strong>Ischémie du fibrome</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Contexte</strong></td>\n            <td>Encore plus fréquente lors de la <strong><span class=\"kw-ci\">grossesse</span></strong> et du <strong>post-partum</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">38–39 °C</span><br>\n              Douleurs pelviennes <strong>intenses</strong><br>\n              <span class=\"kw-clinique\">Métrorragies</span> de sang <strong>noirâtre</strong> (parfois)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">TV</span></strong></td>\n            <td>Augmentation du volume du fibrome · douloureux à la palpation</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td>\n            <td>Image en <em>« cocarde »</em> avec <strong>hyperéchogénicité centrale</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td>\n              <strong>Médical</strong> :<br>\n              · Repos au lit + glace sur le ventre<br>\n              · <span class=\"kw-ttt\">Antalgiques</span> + <span class=\"kw-ttt\">AINS</span> (<span class=\"kw-alerte\">CI si grossesse</span>)<br>\n              · Antibiotiques si surinfection suspectée\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Complications obstétricales et gravidiques</h4>\n\n      <p>Retentissement <em>global modéré</em> une fois la <span class=\"kw-ci\">grossesse</span> installée, mais risque majoré de <strong><span class=\"kw-alerte\">hospitalisation</span>, césarienne, complications du post-partum</strong>.</p>\n\n      <ul>\n        <li><strong>Infertilité, fausses couches spontanées</strong> : si fibrome sous-muqueux déformant la cavité</li>\n        <li><strong><span class=\"kw-alerte\">Menace</span> d’accouchement prématuré / prématurité</strong> : si nécrobiose aseptique (plus fréquente en <span class=\"kw-ci\">grossesse</span>)</li>\n        <li><strong>Localisation praevia</strong> gênant l’accouchement par voie basse</li>\n        <li><strong>Présentation dystocique</strong> si fibrome volumineux interstitiel</li>\n        <li><strong>Dystocie dynamique / hémorragie de la délivrance</strong> : mauvaise rétraction utérine</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Devant <em><span class=\"kw-clinique\">fièvre</span> + douleur pelvienne intense chez une femme enceinte connue pour un fibrome</em>, évoquer la <strong>nécrobiose aseptique</strong>. <span class=\"kw-alerte\">AINS contre-indiqués pendant la grossesse</span> — <span class=\"kw-ttt\">antalgiques</span> de palier adapté + repos + glace.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 23 — Grossesse normale</em></p>","frequence":0,"liens":[{"href":"https://onclepaul.fr/wp-content/uploads/2011/07/N%C3%A9crobiose-fibrome-ut%C3%A9rin.pdf","label":"Onclepaul — Nécrobiose de fibrome utérin (PDF)"}]},{"id":"44-6","rang":"B","rubrique":"Étiologies","titre":"Connaître les étiologies des kystes ovarien","contenu":"<p>Deux grandes familles, qu’il faut absolument distinguer (cf. obj-7) car la conduite à tenir diffère.</p>\n\n      <table >\n        <thead>\n          <tr><th>Famille</th><th>Mécanisme / type</th><th>Exemples</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Kystes fonctionnels</strong><br><em>(les plus fréquents)</em></td>\n            <td>Anomalie d’un follicule au cours du cycle · <strong>régressent spontanément</strong></td>\n            <td>· <strong><span class=\"kw-etio\">Kyste folliculaire</span></strong> (follicule non rompu)<br>· <strong><span class=\"kw-etio\">Kyste lutéal</span></strong> (corps jaune persistant)</td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Kystes organiques</strong><br><em>(persistants → <span class=\"kw-ttt\">exérèse</span>)</em></td>\n            <td><strong>Épithéliaux</strong> (<span class=\"kw-chiffre\">~ 90 %</span> des organiques)</td>\n            <td><strong><span class=\"kw-etio\">Cystadénome séreux</span></strong>, <strong>mucineux</strong>, endométrioïde · tumeur de Brenner</td>\n          </tr>\n          <tr>\n            <td><strong>Germinaux</strong></td>\n            <td><strong><span class=\"kw-etio\">Tératome mature = kyste dermoïde</span></strong> (cheveux, dents, graisse)</td>\n          </tr>\n          <tr>\n            <td><strong>Endométriosique</strong></td>\n            <td><strong><span class=\"kw-etio\">Endométriome</span></strong> (« kyste chocolat ») → rechercher une endométriose profonde associée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <em>Fonctionnel</em> = transitoire, <span class=\"kw-def\">surveillance</span> écho à <span class=\"kw-chiffre\">3 mois</span>. <em>Organique</em> = persiste après <span class=\"kw-chiffre\">3 mois</span> → cœlioscopie (<span class=\"kw-ttt\">kystectomie / annexectomie</span>). Toute zone <strong>solide / végétation</strong> fait craindre une tumeur <span class=\"kw-alerte\">borderline ou maligne</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 306 — Tumeur de l’ovaire · 41 — Endométriose</em></p>","frequence":0},{"id":"44-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","contenu":"<h4>Circonstances de découverte</h4>\n\n      <ul>\n        <li><strong>Le plus souvent asymptomatique</strong> → découverte <em>fortuite</em> (examen, <span class=\"kw-imagerie\">échographie</span>)</li>\n        <li><strong>Syndrome de <span class=\"kw-clinique\">masse</span> pelvienne</strong> si volumineux : <span class=\"kw-clinique\">pesanteur</span>, augmentation du volume abdominal, signes de compression (vésicale, digestive)</li>\n        <li><strong>Douleur pelvienne</strong> → fait évoquer une <span class=\"kw-alerte\">complication</span> (torsion, hémorragie intra-kystique, <span class=\"kw-alerte\">rupture</span> — cf. obj-8)</li>\n      </ul>\n\n      <h4>Examen clinique — toucher vaginal</h4>\n\n      <p>Le kyste ovarien donne classiquement une <strong><span class=\"kw-clinique\">masse</span> latéro-utérine <span class=\"kw-clinique\">indépendante</span> de l’utérus</strong> :</p>\n      <ul>\n        <li><strong>Séparée de l’utérus par un sillon</strong>, ne transmet pas les mouvements (main abdominale ↔ doigts vaginaux)</li>\n        <li><strong>Régulière et mobile</strong> → oriente vers un kyste bénin (ou un fibrome pédiculé)</li>\n        <li><strong>Irrégulière et fixée</strong> → fait craindre un <span class=\"kw-alerte\">cancer de l’ovaire</span>, une endométriose ou une cause infectieuse</li>\n      </ul>\n\n      <p>Compléter par l’<strong>examen abdominal</strong> (pôle supérieur si grande taille, recherche d’<span class=\"kw-clinique\">ascite</span> / <span class=\"kw-clinique\">hépatomégalie</span> → orientation maligne) et le <strong>toucher rectal</strong>.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span class=\"kw-clinique\">Masse</span> <em>indépendante de l’utérus + régulière + mobile</em> = profil bénin. Tout caractère <em>fixé, irrégulier, avec ascite</em> = <span class=\"kw-alerte\">suspicion de malignité</span> → <span class=\"kw-imagerie\">échographie</span> puis <span class=\"kw-imagerie\">IRM</span> + marqueurs.\n      </div>","frequence":0},{"id":"44-8","rang":"A","rubrique":"Étiologies","titre":"Savoir différencier kystes fonctionnel et organique","contenu":"<p>La distinction repose sur les <strong>critères échographiques de bénignité</strong> et sur l’<strong><span class=\"kw-clinique\">évolution</span> à <span class=\"kw-chiffre\">3 mois</span></strong>.</p>\n\n      <h4>Critères échographiques de bénignité</h4>\n      <p>(doivent être <strong>tous présents</strong>)</p>\n      <ul>\n        <li>Image <strong>uniloculaire</strong> (ou cloison fine <span class=\"kw-chiffre\">&lt; 3 mm</span>)</li>\n        <li><span class=\"kw-radio\">Anéchogène pur, sans zone solide ni végétation</span></li>\n        <li><strong>Paroi fine</strong></li>\n        <li>Vascularisation <strong>périphérique régulière</strong> (index de résistance <span class=\"kw-chiffre\">&gt; 0,50</span>)</li>\n        <li>Taille <span class=\"kw-chiffre\">&lt; 7 cm</span></li>\n        <li><strong>Absence d’<span class=\"kw-clinique\">ascite</span></strong></li>\n      </ul>\n\n      <table >\n        <thead>\n          <tr><th></th><th>Kyste fonctionnel</th><th>Kyste organique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Critères de</span> bénignité</strong></td>\n            <td>Tous présents</td>\n            <td><span class=\"kw-chiffre\">≥ 1</span> critère manquant possible</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td><strong>Régression</strong> à l’écho de contrôle à <span class=\"kw-chiffre\">3 mois</span></td>\n            <td><strong>Persiste</strong> &gt; <span class=\"kw-chiffre\">3 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong>CAT</strong></td>\n            <td><span class=\"kw-ttt\">Simple surveillance</span> (pas de blocage ovarien)</td>\n            <td><span class=\"kw-def\">Surveillance</span> ou <strong><span class=\"kw-ttt\">exérèse cœlioscopique</span></strong> (<span class=\"kw-ttt\">kystectomie / annexectomie</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège EDN.</strong> En présence de <em>tous</em> les <span class=\"kw-def\">critères de</span> bénignité → <strong>écho de contrôle à <span class=\"kw-chiffre\">3 mois</span></strong> (pour éliminer un fonctionnel), <span class=\"kw-alerte\">pas de chirurgie d’emblée</span>. À l’inverse, <strong>aucun <span class=\"kw-def\">critère de</span> bénignité</strong> ou zone solide → <span class=\"kw-imagerie\">IRM</span> ± marqueurs (<span class=\"kw-bio\">CA-125</span>), voire cœlioscopie.\n      </div>","frequence":0},{"id":"44-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications des kystes ovariens","contenu":"<p>Les complications d’un kyste ovarien sont des <strong>urgences douloureuses</strong> qu’il faut savoir évoquer devant une douleur pelvienne aiguë.</p>\n\n      <table >\n        <thead>\n          <tr><th>Complication</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Torsion d’annexe</span></strong></td>\n            <td>La plus grave — <span class=\"kw-alerte\">urgence</span> chirurgicale (cf. obj-9) · risque de <strong><span class=\"kw-clinique\">nécrose</span> ovarienne</strong> · favorisée par les kystes lourds (<span class=\"kw-etio\">dermoïde</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Hémorragie intra-kystique</span></strong></td>\n            <td>Douleur brutale · hyperdensité du contenu à l’imagerie · le plus souvent résolutive sous traitement médical</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Rupture de kyste</span></strong></td>\n            <td>Douleur brutale + <span class=\"kw-clinique\">épanchement</span> du Douglas · risque d’<span class=\"kw-alerte\">hémopéritoine</span> si <span class=\"kw-alerte\">rupture</span> <span class=\"kw-etio\">hémorragique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Abcédation / infection</strong></td>\n            <td>Plus rare · contexte <span class=\"kw-etio\">infectieux</span> (<span class=\"kw-clinique\">abcès</span> ovarien)</td>\n          </tr>\n          <tr>\n            <td><strong>Dégénérescence maligne</strong></td>\n            <td>Surtout les kystes <strong>organiques</strong> persistants · à craindre devant une zone solide / végétation</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Réflexe.</strong> Devant une <em>douleur pelvienne aiguë + <span class=\"kw-clinique\">masse</span> annexielle</em>, penser en premier à la <span class=\"kw-alerte\">torsion d’annexe</span> (cf. obj-9) — c’est la complication qui impose une <strong><span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span></strong> pour sauver l’ovaire.\n      </div>","frequence":0},{"id":"44-10","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer une torsion d’annexe","contenu":"<p>La <span class=\"kw-alerte\">torsion d’annexe</span> est une <strong><span class=\"kw-alerte\">urgence</span> chirurgicale</strong> : la torsion du pédicule ovarien interrompt la vascularisation → <strong>ischémie puis <span class=\"kw-clinique\">nécrose</span></strong> de l’ovaire. Le <span class=\"kw-def\">pronostic</span> <em>fonctionnel ovarien</em> dépend de la rapidité de la prise en charge.</p>\n\n      <h4>Quand l’évoquer ?</h4>\n      <ul>\n        <li><strong>Douleur pelvienne brutale</strong>, unilatérale, <em>en coup de poignard</em></li>\n        <li><strong>Signes digestifs</strong> trompeurs : <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span></li>\n        <li><span class=\"kw-def\">Terrain</span> : <strong>kyste ovarien</strong> connu (surtout volumineux / lourd type <strong><span class=\"kw-etio\">dermoïde</span></strong>)</li>\n      </ul>\n\n      <h4>Confirmation</h4>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Échographie pelvienne avec écho-Doppler</span></strong> : <span class=\"kw-clinique\">masse</span> annexielle + <strong>anomalie / arrêt du flux du pédicule ovarien</strong></li>\n        <li>Un Doppler <em>normal n’élimine pas</em> le diagnostic (torsion intermittente) → la clinique prime</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>CAT — <span class=\"kw-alerte\">urgence</span>.</strong> <span class=\"kw-alerte\">Cœlioscopie en urgence &lt; 6 h</span> idéalement : <strong><span class=\"kw-ttt\">détorsion</span></strong> + kystectomie. Détorsion conservatrice possible au-delà si reprise de coloration peropératoire (reco CNGOF) — <strong>conservation ovarienne même si aspect initialement nécrotique</strong>. Ne jamais retarder pour des examens.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 130\" role=\"img\" aria-label=\"Frise de la conduite à tenir devant une suspicion de torsion d'annexe : douleur pelvienne brutale unilatérale, puis échographie pelvienne avec écho-Doppler — un Doppler normal n'élimine pas le diagnostic —, puis cœlioscopie en urgence en moins de 6 heures, et enfin détorsion conservatrice avec kystectomie.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Torsion d'annexe — urgence chirurgicale</text>\n          <rect class=\"fb-red\" x=\"8\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"70.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Douleur pelvienne</text>\n          <text class=\"tx-red\" x=\"70.5\" y=\"80\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">brutale</text>\n          <text class=\"tx-red\" x=\"70.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7.5\">unilatérale</text>\n          <rect class=\"fb-blue\" x=\"147\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\"><span class=\"kw-imagerie\">Échographie</span> +</text>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"80\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\"><span class=\"kw-imagerie\">écho-Doppler</span></text>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7\">Doppler normal n'exclut pas</text>\n          <rect class=\"fb-red\" x=\"286\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"348.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Cœlioscopie</text>\n          <text class=\"tx-red\" x=\"348.5\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">&lt;<span class=\"kw-chiffre\"> 6 h</span></text>\n          <text class=\"tx-red\" x=\"348.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7.5\">urgence — ne pas retarder</text>\n          <rect class=\"fb-ok\" x=\"425\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Détorsion</text>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"80\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">conservatrice</text>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7.5\">+ kystectomie</text>\n          <line class=\"ln\" x1=\"135\" y1=\"78\" x2=\"144\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"147,78 141,74 141,82\"/>\n          <line class=\"ln\" x1=\"274\" y1=\"78\" x2=\"283\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"286,78 280,74 280,82\"/>\n          <line class=\"ln\" x1=\"413\" y1=\"78\" x2=\"422\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"425,78 419,74 419,82\"/>\n        </svg>\n        <figcaption>La clinique prime : un écho-Doppler normal n’élimine pas le diagnostic — cœlioscopie en urgence &lt;<span class=\"kw-chiffre\"> 6 h</span>, détorsion conservatrice (conserver l’ovaire même d’aspect nécrotique).</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 40 — Algies pelviennes chez la femme · 306 — Tumeur de l’ovaire</em></p>","frequence":0},{"id":"44-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les deux principaux examens radiologiques complémentaires à réaliser en cas de tuméfaction pelvienne et leur hiérarchisation (première et deuxième intention)","contenu":"<h4>Hiérarchisation EDN — fibrome utérin</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Place</th><th>Description sémiologique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne</strong></td>\n            <td><strong>1ʳᵉ intention</strong> — examen qui fait le diagnostic</td>\n            <td>\n              · Formations <strong>homogènes</strong>, <span class=\"kw-radio\">hypoéchogènes</span> par rapport au reste du myomètre<br>\n              · Généralement <strong>bien limitées</strong><br>\n              · <span class=\"kw-radio\">Encorbellement vasculaire</span> caractéristique<br>\n              · Nécrobiose : <span class=\"kw-radio\">image en « cocarde » avec hyperéchogénicité centrale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> pelvienne</strong></td>\n            <td><strong>2ᵉ intention</strong></td>\n            <td>\n              Indications :<br>\n              · <span class=\"kw-clinique\">Masse</span> <span class=\"kw-chiffre\">&gt; 10 cm</span><br>\n              · Nombre de fibromes <span class=\"kw-chiffre\">&gt; 5</span><br>\n              · <span class=\"kw-imagerie\">Échographie</span> insuffisante\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan <span class=\"kw-ttt\">biologique</span> d’accompagnement</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">NFS</span> + <span class=\"kw-bio\">ferritine</span></strong> : rechercher une anémie ferriprive (complication des ménométrorragies)</li>\n        <li><strong>β-hCG</strong> systématique en âge de procréer avant toute exploration</li>\n        <li><span class=\"kw-def\">Bilan préopératoire</span> si <span class=\"kw-ttt\">chirurgie</span> envisagée</li>\n      </ul>\n\n      <h4>Hiérarchisation EDN — <span class=\"kw-clinique\">masse</span> ovarienne</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Place</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne</strong><br>(sus-pubienne + endovaginale)</td>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td>Classe la <span class=\"kw-clinique\">masse</span> : <strong>kyste fonctionnel</strong> <span class=\"kw-bio\">vs</span> <strong>organique</strong> <span class=\"kw-bio\">vs</span> <strong><span class=\"kw-def\">critères de</span> malignité</strong> · recherche d’<span class=\"kw-clinique\">ascite</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> pelvienne</strong></td>\n            <td><strong>2ᵉ intention</strong></td>\n            <td>Origine indéterminée · <span class=\"kw-def\">critères de</span> malignité · <strong><span class=\"kw-clinique\">masse</span> uniloculaire pure <span class=\"kw-chiffre\">&gt; 7 cm</span></strong> (Se de l’écho moins bonne sur gros kyste)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> abdomino-pelvien</strong></td>\n            <td>Bilan d’extension</td>\n            <td>Si suspicion de <span class=\"kw-alerte\">malignité</span> / carcinose (atteinte hépatique, <span class=\"kw-clinique\">adénopathies</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Marqueurs tumoraux (si <span class=\"kw-clinique\">masse</span> suspecte)</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">CA-125</span></strong> (± HE4, <span class=\"kw-bio\">ACE</span>, <span class=\"kw-bio\">CA 19-9</span>) : devant une tumeur ovarienne suspecte — <em>inutile sur un kyste manifestement bénin</em></li>\n        <li><strong><span class=\"kw-bio\">LDH</span>, α-fœtoprotéine, hCG</strong> : si suspicion de <strong>tumeur germinale</strong> (femme jeune)</li>\n        <li><strong>Estradiol, AMH, inhibine B</strong> : si signes d’hyperœstrogénie / tumeur de la granulosa</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Synthèse 1ʳᵉ/2ᵉ intention.</strong> Quelle que soit la <span class=\"kw-clinique\">tuméfaction</span> (utérine ou ovarienne) : <strong><span class=\"kw-imagerie\">échographie pelvienne</span> en 1ʳᵉ intention</strong>, <strong><span class=\"kw-imagerie\">IRM</span> en 2ᵉ intention</strong> sur les masses complexes / volumineuses / indéterminées. Précéder de la <span class=\"kw-bio\">β-hCG</span> en âge de procréer.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"Radiopaedia : Hystérosalpingographie (HSG)"}]},{"id":"44-12","rang":"A","rubrique":"Définition","titre":"Définir le prolapsus génital de la femme","contenu":"<p>Le <span class=\"kw-def\">prolapsus génital</span> est une <strong>hernie des organes pelviens à travers le vagin</strong> — il s’extériorise par <strong><span class=\"kw-clinique\">tuméfaction vaginale</span></strong>, <em>non palpable au niveau abdominal</em>. C’est la différence fondamentale avec un fibrome ou une <span class=\"kw-clinique\">masse</span> annexielle.</p>\n\n      <h4>Rappels anatomiques</h4>\n\n      <ul>\n        <li><strong>Pelvis</strong> : compartiment entre le détroit supérieur et le plancher pelvien (muscle <em><span class=\"kw-def\">levator ani</span></em>)</li>\n        <li><strong>Périnée</strong> : sous le plan du <span class=\"kw-def\">levator ani</span> · orifices vulvaire et anal · fosses ischiorectales</li>\n        <li>Le pelvis contient d’avant en arrière : <strong>bas appareil urinaire</strong> (urètre, vessie) · <strong>appareil génital</strong> (ovaires, trompes, utérus, vagin) · <strong>appareil digestif</strong> (rectum, canal anal, ± sigmoïde, caecum)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> <em><span class=\"kw-etio\">Rectocèle</span> ≠ prolapsus rectal</em>. La rectocèle = rectum qui bombe à travers le vagin. Le prolapsus rectal = extériorisation du rectum <strong>par l’anus</strong> (item HGE).\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/pelvic-organ-prolapse","label":"Radiopaedia : Pelvic organ prolapse"}]},{"id":"44-13","rang":"B","rubrique":"Définition","titre":"Définir les différents compartiments du prolapsus","contenu":"<p>Deux nomenclatures coexistent (selon que l’on décrit la <em>paroi vaginale</em> qui descend ou <em>l’organe</em> qui bombe).</p>\n\n      <table >\n        <thead>\n          <tr><th>Étage</th><th>Paroi vaginale (colpocèle)</th><th>Organe extériorisé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Antérieur</strong></td>\n            <td>Colpocèle antérieur (face antérieure du vagin)</td>\n            <td><strong><span class=\"kw-etio\">Cystocèle</span></strong> = <em>vessie</em></td>\n          </tr>\n          <tr>\n            <td><strong>Moyen</strong></td>\n            <td>Colpocèle apical (apex du vagin)</td>\n            <td><strong><span class=\"kw-etio\">Hystérocèle / hystéroptose</span></strong> = <em>utérus</em></td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Postérieur</strong></td>\n            <td rowspan=\"3\">Colpocèle postérieur (face postérieure du vagin)</td>\n            <td><strong><span class=\"kw-etio\">Rectocèle</span></strong> = <em>rectum</em></td>\n          </tr>\n          <tr><td><strong><span class=\"kw-etio\">Élytrocèle</span></strong> = <em>cul-de-sac recto-utérin (Douglas)</em></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Entérocèle</span></strong> = <em>intestin</em></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"44-14","rang":"B","rubrique":"Diagnostic positif","titre":"Citer les diagnostics différentiels du prolapsus génital de la femme","contenu":"<p>Devant une <strong><span class=\"kw-clinique\">tuméfaction vaginale</span> extériorisée</strong>, plusieurs diagnostics imitent le prolapsus. Le <span class=\"kw-alerte\">TV</span>/TR et l’<span class=\"kw-imagerie\">échographie</span> aident à les écarter.</p>\n\n      <ul>\n        <li><strong><span class=\"kw-etio\">Kyste vaginal</span></strong> (ex. kyste du canal de Gartner)</li>\n        <li><strong><span class=\"kw-etio\">Fibrome de la cloison vésico-vaginale</span></strong> / fibrome accouché par le col</li>\n        <li><strong><span class=\"kw-etio\">Polype cervical extériorisé</span></strong></li>\n        <li><strong><span class=\"kw-clinique\">Ascite</span></strong> : peut <em>provoquer ou aggraver</em> l’extériorisation d’un prolapsus</li>\n        <li><strong><span class=\"kw-etio\">Prolapsus rectal</span></strong> (extériorisation du rectum <em>par l’anus</em> — à ne pas confondre avec une rectocèle)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche.</strong> <span class=\"kw-imagerie\">Échographie abdomino-pelvienne</span> souvent demandée pour <em>éliminer</em> un kyste vaginal, un fibrome de la cloison vésico-vaginale ou une ascite. Au <span class=\"kw-alerte\">TV</span>/TR, le prolapsus <strong>ne contient pas de <span class=\"kw-clinique\">masse</span></strong> propre — c’est un point distinctif.\n      </div>","frequence":0},{"id":"44-15","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence du prolapsus","contenu":"<table >\n        <thead>\n          <tr><th>Âge</th><th><span class=\"kw-def\">Prévalence</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Jusqu’à<span class=\"kw-chiffre\"> 50 ans</span></strong></td>\n            <td>Augmente avec l’âge : <span class=\"kw-chiffre\">3–11 %</span> au questionnaire <span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">30–90 %</span> cliniquement</td>\n          </tr>\n          <tr>\n            <td><strong>Après <span class=\"kw-chiffre\">50 ans</span></strong></td>\n            <td><span class=\"kw-def\">Prévalence</span> <strong>stable</strong>, mais le <strong><span class=\"kw-def\">grade</span> du prolapsus augmente</strong> avec l’âge</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L’écart majeur entre <span class=\"kw-def\">prévalence</span> <em>au questionnaire</em> (<span class=\"kw-chiffre\">3–11 %</span>) et <em>clinique</em> (<span class=\"kw-chiffre\">30–90 %</span>) explique qu’un <strong>grand nombre de prolapsus sont asymptomatiques</strong>. Le traitement n’est proposé que <em>si la patiente est gênée</em>. <em>(FR détaillés dans l’onglet « Astuces PU &amp; Pièges ».)</em>\n      </div>","frequence":1},{"id":"44-16","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques du prolapsus","contenu":"<h4>Symptôme principal</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Pesanteur pelvienne</span></strong> et <strong>sensation de boule à la vulve</strong></li>\n        <li><strong>Augmentée à l’orthostatisme</strong> et en <strong>fin de journée</strong></li>\n      </ul>\n\n      <h4>Signes fonctionnels associés</h4>\n\n      <table >\n        <thead>\n          <tr><th>Système</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Urinaires</strong></td>\n            <td>\n              · Syndrome d’<strong>hyperactivité vésicale</strong> : <span class=\"kw-clinique\">urgenturie</span>, IUU<br>\n              · Trouble de la <strong>vidange vésicale</strong> aux stades avancés : <span class=\"kw-clinique\">dysurie</span>, RPM, <span class=\"kw-def\">infection urinaire</span> récidivante, <span class=\"kw-alerte\">RAU</span><br>\n              · Manœuvres digitales de réintroduction parfois nécessaires pour la miction<br>\n              · Mécanisme : <em>plicature/compression de l’urètre lors de l’extériorisation du prolapsus</em> = « effet pelote » (obstacle sous-vésical)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Digestifs</strong> (rectocèles)</td>\n            <td>\n              · <strong>Faux besoins</strong> pouvant conduire à des épisodes d’incontinence (<span class=\"kw-etio\">fécalome</span> = fausse <span class=\"kw-clinique\">diarrhée</span>)<br>\n              · <strong><span class=\"kw-clinique\">Dyschésie</span></strong> (exonération difficile) — manœuvres digitales parfois nécessaires\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Génito-sexuels</strong></td>\n            <td>\n              · <strong><span class=\"kw-clinique\">Dyspareunie</span></strong><br>\n              · Sensation de <strong><span class=\"kw-clinique\">béance vulvaire</span></strong> conduisant à l’arrêt de l’activité sexuelle\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signe négatif</strong></td>\n            <td>Le prolapsus génital <em>n’est habituellement pas douloureux</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen clinique</h4>\n\n      <ul>\n        <li><strong>Examen gynécologique aux valves</strong> : détermine l’étage pelvien concerné</li>\n        <li><strong><span class=\"kw-alerte\">TV</span> / TR</strong> : recherche des diagnostics différentiels — <em>pas de <span class=\"kw-clinique\">masse</span></em> dans le prolapsus</li>\n        <li><strong>Rechercher une IUE masquée</strong> par le prolapsus :\n          <ul>\n            <li><em>Comment ?</em> <strong>Test d’effort de poussée abdominale et de <span class=\"kw-clinique\">toux</span></strong> avec <strong>vessie pleine + prolapsus réduit</strong></li>\n            <li><em>Mécanisme</em> : IUE masquée par la plicature/compression de l’urètre par le prolapsus</li>\n          </ul>\n        </li>\n        <li><strong>Qualité de vie</strong> : questionnaire validé <strong><span class=\"kw-def\">PFDI-20</span></strong> (Pelvic Floor Distress Inventory)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège thérapeutique.</strong> Les SFU associés ne sont pas spécifiques du prolapsus. Il faut prévenir la patiente : la <span class=\"kw-ttt\">chirurgie</span> corrigera la sensation de boule vaginale mais <em>ne corrige pas toujours les SFU associés</em>, qui peuvent être indépendants.\n      </div>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Torsion d’annexe <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> chirurgicale</span></strong></p><p><span class=\"kw-alerte\">Cœlioscopie en urgence &lt; 6 h</span> : <span class=\"kw-ttt\">détorsion conservatrice</span> + kystectomie (conserver l’ovaire même d’aspect nécrotique)</p><ul><li>Douleur pelvienne <span class=\"kw-clinique\">brutale</span> unilatérale + <span class=\"kw-clinique\">nausées / vomissements</span>, sur kyste connu (surtout <span class=\"kw-etio\">dermoïde</span>)</li><li><span class=\"kw-imagerie\">Écho-Doppler</span> : arrêt du flux du pédicule — un Doppler normal <strong>n’élimine pas</strong> le diagnostic (la clinique prime)</li></ul><p><strong>Hémorragie intra-kystique / <span class=\"kw-alerte\">rupture</span> de kyste</strong></p><p>Le plus souvent résolutif sous <span class=\"kw-ttt\">traitement médical</span> ; <span class=\"kw-ttt\">chirurgie</span> si instabilité / hémopéritoine</p><ul><li>Douleur <span class=\"kw-clinique\">brutale</span> ± <span class=\"kw-clinique\">épanchement du Douglas</span></li><li>Risque d’<span class=\"kw-alerte\">hémopéritoine</span> si <span class=\"kw-alerte\">rupture</span> <span class=\"kw-etio\">hémorragique</span></li></ul>","redflags":"<ul><li><span class=\"kw-clinique\">Masse</span> <span class=\"kw-alerte\">irrégulière, fixée</span> au toucher vaginal</li><li><span class=\"kw-clinique\">Masse</span> à <span class=\"kw-alerte\">progression rapide</span> (évoque un sarcome utérin)</li><li><span class=\"kw-clinique\">Ascite</span> associée</li><li>Survenue <span class=\"kw-alerte\">après la ménopause</span></li><li>Zone <span class=\"kw-radio\">solide / végétation</span> ou cloison épaisse à l’<span class=\"kw-imagerie\">échographie</span></li></ul>","principes":"<p>Traiter <strong>si symptomatique</strong> ou suspect ; <span class=\"kw-ttt\">abstention / surveillance</span> possible si bénin et asymptomatique.</p><p><strong>Fibrome utérin</strong></p><ul><li><span class=\"kw-ttt\">Abstention</span> si asymptomatique</li><li>Médical (saignements) : <span class=\"kw-ttt\">acide tranexamique</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">progestatifs</span>, <span class=\"kw-ttt\">DIU au lévonorgestrel</span> (hors sous-muqueux)</li><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">myomectomie</span> (conservatrice) ou <span class=\"kw-ttt\">hystérectomie</span> ; <span class=\"kw-ttt\">embolisation</span> des artères utérines (pas sur sous-muqueux)</li></ul><p><strong>Kyste ovarien</strong></p><ul><li>Fonctionnel → <span class=\"kw-ttt\">surveillance</span>, contrôle <span class=\"kw-imagerie\">écho</span> à <span class=\"kw-chiffre\">3 mois</span></li><li>Organique (persiste &gt;<span class=\"kw-chiffre\"> 3 mois</span>) → <span class=\"kw-ttt\">exérèse cœlioscopique</span> (kystectomie / annexectomie)</li></ul><p><strong>Prolapsus génital <span class=\"q\">— uniquement si gênant</span></strong></p><ul><li><span class=\"kw-ttt\">Rééducation périnéale</span> (stades 1-2)</li><li><span class=\"kw-ttt\">Pessaire</span> (stades 2-4)</li><li><span class=\"kw-ttt\">Chirurgie</span> si échec : <span class=\"kw-ttt\">promontofixation</span> cœlioscopique ou voie vaginale</li><li>Correction des FR modifiables : <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-etio\">obésité</span></li></ul>","suivi":"<p><strong>Kyste fonctionnel :</strong> <span class=\"kw-imagerie\">écho</span> de contrôle à <span class=\"kw-chiffre\">3 mois</span> (régression attendue ; persistance → organique).<br><strong>Fibrome :</strong> <span class=\"kw-clinique\">régression habituelle après la ménopause</span> ; surveiller l’<span class=\"kw-bio\">anémie ferriprive</span>.<br><strong>Prolapsus :</strong> <span class=\"kw-clinique\">évolution</span> vers l’<span class=\"kw-alerte\">aggravation</span> sans correction des FR ; prévenir que la <span class=\"kw-ttt\">chirurgie</span> ne corrige pas toujours les SFU.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/uterine-leiomyoma","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/figo-classification-system-foruterine-leiomyoma","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"radiopaedia.org"},{"href":"https://onclepaul.fr/wp-content/uploads/2011/07/N%C3%A9crobiose-fibrome-ut%C3%A9rin.pdf","label":"onclepaul.fr"},{"href":"https://radiopaedia.org/articles/pelvic-organ-prolapse","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Tuméfaction pelvienne (femme en âge de procréer) — 1er réflexe : éliminer une grossesse — β-hCG","detail":"<h4>CAT — démarche diagnostique devant une <span class=\"kw-clinique\">tuméfaction</span> pelvienne — 1er réflexe = β-hCG, puis tri topographique au toucher vaginal</h4>","branches":[{"to":"t-grossesse","label":"β-hCG positive","color":"blue"},{"to":"q-topo","label":"β-hCG négative","color":"blue"}]},{"id":"t-grossesse","kind":"terminal","label":"Grossesse (utérus gravide)","color":"blue","detail":"<h4>Clinique</h4><ul><li>Utérus <span class=\"kw-clinique\">augmenté de volume et mou</span> dans un contexte de <span class=\"kw-clinique\">retard de règles</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">Échographie pelvienne</span> pour localiser la <span class=\"kw-ci\">grossesse</span> (intra ou extra-utérine)</li></ul><h4>Renvoi</h4><ul><li>Item 23 (<span class=\"kw-ci\">grossesse</span> normale) · Item 25 (grossesse extra-utérine)</li></ul>"},{"id":"q-topo","kind":"decision","label":"Topographie de la masse au toucher vaginal ? — Dépendance vis-à-vis de l’utérus + siège (abdominal vs vaginal)","branches":[{"to":"t-fibrome","label":"Médiane, dépendante de l’utérus","color":"blue"},{"to":"q-annexe","label":"Latéro-utérine, indépendante de l’utérus","color":"blue"},{"to":"t-prolapsus","label":"Tuméfaction vaginale extériorisée, ↑ à la poussée","color":"blue"}]},{"id":"t-fibrome","kind":"terminal","label":"Origine utérine — fibrome","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Ménométrorragies</span> (surtout fibrome sous-muqueux) → <span class=\"kw-alerte\">anémie ferriprive</span></li><li><span class=\"kw-clinique\">Syndrome de masse pelvienne</span> (compression) si volumineux / sous-séreux</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> en 1re intention (<span class=\"kw-clinique\">nodule</span> <span class=\"kw-radio\">hypoéchogène</span>, encorbellement vasculaire) ; <span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-chiffre\">2e intention</span> si &gt;<span class=\"kw-chiffre\"> 10 cm</span> ou &gt; 5 fibromes</li></ul><h4>À distinguer</h4><ul><li>Diagnostics utérins plus rares : <span class=\"kw-etio\">adénomyose</span>, <span class=\"kw-alerte\">sarcome</span>, <span class=\"kw-etio\">cancer de l’endomètre</span></li></ul>"},{"id":"q-annexe","kind":"decision","label":"Caractères de la masse annexielle ? — Douleur aiguë ? critères échographiques de bénignité ? signes de malignité ?","branches":[{"to":"t-torsion","label":"Douleur aiguë brutale + masse","color":"red"},{"to":"t-fonctionnel","label":"Tous critères de bénignité présents","color":"green"},{"to":"t-organique","label":"≥ 1 critère manquant / persiste > 3 mois","color":"amber"},{"to":"t-malin","label":"Fixée / irrégulière · ascite · ménopause · zone solide","color":"red"}]},{"id":"t-torsion","kind":"terminal","label":"Complication aiguë (torsion +++)","color":"red","detail":"<h4>Clinique</h4><ul><li>Douleur <span class=\"kw-clinique\">brutale</span> unilatérale + <span class=\"kw-clinique\">nausées / vomissements</span> ; <span class=\"kw-def\">terrain</span> de kyste lourd (<span class=\"kw-etio\">dermoïde</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">Écho-Doppler</span> puis <span class=\"kw-alerte\">cœlioscopie en urgence &lt; 6 h</span> (<span class=\"kw-ttt\">détorsion</span> conservatrice)</li></ul><h4>Renvoi</h4><ul><li>Item 40 (algies pelviennes) · Item 306 (tumeurs de l’ovaire)</li></ul>"},{"id":"t-fonctionnel","kind":"terminal","label":"Kyste ovarien fonctionnel","color":"green","detail":"<h4>Critères écho</h4><ul><li>Uniloculaire, <span class=\"kw-radio\">anéchogène pur</span>, paroi fine, &lt; <span class=\"kw-chiffre\">7 cm</span>, sans <span class=\"kw-clinique\">ascite</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Surveillance</span> — <span class=\"kw-imagerie\">écho</span> de contrôle à <span class=\"kw-chiffre\">3 mois</span> (régression attendue)</li></ul>"},{"id":"t-organique","kind":"terminal","label":"Kyste ovarien organique","color":"amber","detail":"<h4>Étiologies</h4><ul><li>Épithélial (~ <span class=\"kw-chiffre\">90 %</span>), <span class=\"kw-etio\">tératome mature (dermoïde)</span>, <span class=\"kw-etio\">endométriome</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">IRM</span> si indéterminé ; <span class=\"kw-ttt\">exérèse cœlioscopique</span> (kystectomie / annexectomie)</li></ul><h4>Renvoi</h4><ul><li>Item 306 (tumeurs de l’ovaire) · Item 41 (endométriose)</li></ul>"},{"id":"t-malin","kind":"terminal","label":"Suspicion de malignité ovarienne","color":"red","detail":"<h4><span class=\"kw-alerte\">Drapeaux rouges</span></h4><ul><li><span class=\"kw-clinique\">Masse</span> <span class=\"kw-alerte\">irrégulière, fixée</span>, <span class=\"kw-clinique\">ascite</span>, <span class=\"kw-radio\">zone solide / végétation</span>, survenue post-ménopause</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">IRM</span> pelvienne + <span class=\"kw-bio\">CA-125</span> (± marqueurs) ; <span class=\"kw-imagerie\">TDM</span> pour bilan d’extension</li></ul><h4>Renvoi</h4><ul><li>Item 306 (tumeurs de l’ovaire)</li></ul>"},{"id":"t-prolapsus","kind":"terminal","label":"Prolapsus génital","color":"blue","detail":"<h4>Clinique</h4><ul><li>Hernie des organes pelviens à travers le vagin, <strong>non palpable</strong> au niveau abdominal ; <span class=\"kw-clinique\">pesanteur</span> + sensation de boule, ↑ en orthostatisme</li></ul><h4>Examen</h4><ul><li>Examen <span class=\"kw-clinique\">aux valves</span> (étage cysto- / hystéro- / rectocèle) ; rechercher une <span class=\"kw-clinique\">IUE masquée</span></li></ul><h4>PEC</h4><ul><li>Seulement si gênant : <span class=\"kw-ttt\">rééducation</span>, <span class=\"kw-ttt\">pessaire</span>, ou <span class=\"kw-ttt\">chirurgie</span></li></ul>"}]},"cards":[{"i":"86f530d01eda","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quel est un repère clinique clé permettant d'orienter le diagnostic vers un fibrome utérin lors de l'examen clinique d'une tuméfaction pelvienne ?","a":"<p>Un repère clinique clé pour le <strong>fibrome utérin</strong> est la palpation d'une <strong>masse dépendante de l'utérus</strong> au toucher vaginal.</p>"},{"i":"960532912607","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Comment différencier cliniquement un utérus gravide d'autres tuméfactions pelviennes chez une femme en âge de procréer ?","a":"<p>Un <strong>utérus gravide</strong> sera généralement <strong>augmenté de volume et mou</strong>, le tout dans un contexte de <strong>retard de règles</strong>.</p>"},{"i":"97d43dd4e710","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quelle est la première étiologie à éliminer systématiquement devant toute tuméfaction pelvienne chez une femme en âge de procréer ?","a":"<p>Devant toute tuméfaction pelvienne chez une femme en âge de procréer, il faut systématiquement éliminer le diagnostic de <strong>grossesse</strong>. Cela se fait par le dosage des <strong>β-hCG</strong>.</p>"},{"i":"a340a64fd761","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quelles sont les 2 étiologies les plus fréquentes de tuméfaction pelvienne chez une femme en âge de procréer, après avoir éliminé une grossesse ?","a":"<p>Après avoir éliminé une grossesse, les 2 étiologies les plus fréquentes de tuméfaction pelvienne sont :</p><ul><li>Le <strong>fibrome utérin</strong> (d'origine utérine).</li><li>Le <strong>kyste de l'ovaire</strong> (d'origine ovarienne).</li></ul>"},{"i":"b26bbc72892e","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quel est un repère clinique clé permettant d'orienter le diagnostic vers un kyste de l'ovaire lors de l'examen clinique d'une tuméfaction pelvienne ?","a":"<p>Un repère clinique clé pour le <strong>kyste de l'ovaire</strong> est la palpation d'une <strong>masse latéro-utérine indépendante de l'utérus</strong>.</p>"},{"i":"0093371e287d","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Quelle est la prise en charge chirurgicale d'une torsion d'annexe ?","a":"<p>La prise en charge est une <strong>cœlioscopie en urgence</strong>, idéalement dans les <strong>6 heures</strong>. Elle consiste en une <strong>détorsion</strong> de l'annexe et une <strong>kystectomie</strong> si un kyste est présent. Une <strong>détorsion conservatrice</strong> est possible même au-delà de 6 heures si une reprise de coloration est observée peropératoirement, et il faut <strong>toujours privilégier la conservation ovarienne</strong>, même si l'ovaire a un aspect initialement nécrotique. Il ne faut <strong>jamais retarder</strong> cette intervention pour des examens complémentaires.</p>"},{"i":"5c1cb6fcfb16","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Quelle est la stratégie diagnostique en cas de suspicion de torsion d'annexe et quelle est la place de l'échographie-Doppler ?","a":"<p>Le diagnostic est confirmé par une <strong>échographie pelvienne avec écho-Doppler</strong>, qui peut montrer une masse annexielle et une anomalie ou un arrêt du flux du pédicule ovarien. Cependant, il est crucial de retenir qu'un <strong>Doppler normal n'élimine pas le diagnostic</strong> (en cas de torsion intermittente par exemple), et que la <strong>clinique prime</strong>.</p>"},{"i":"826bc47a7858","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Comment définir et caractériser la gravité de la torsion d'annexe ?","a":"<p>La torsion d'annexe est une <strong>urgence chirurgicale</strong> où la torsion du pédicule ovarien interrompt la vascularisation. Cela entraîne une <strong>ischémie</strong> puis une <strong>nécrose de l'ovaire</strong>. Le pronostic fonctionnel ovarien dépend directement de la rapidité de la prise en charge.</p>"},{"i":"a12f4bbece93","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Quels signes cliniques doivent faire évoquer une torsion d'annexe ?","a":"<ul><li>Une <strong>douleur pelvienne brutale</strong>, <strong>unilatérale</strong>, en <strong>coup de poignard</strong>.</li><li>Des signes digestifs souvent trompeurs, notamment des <strong>nausées</strong> et des <strong>vomissements</strong>.</li><li>Un terrain évocateur, par exemple la présence d'un <strong>kyste ovarien connu</strong> (en particulier volumineux ou lourd, comme un dermoïde).</li></ul>"},{"i":"4442d9c51e4c","n":44,"o":"44-12","u":"Définition","t":"Définir le prolapsus génital de la femme","q":"Quelle est la différence entre une rectocèle et un prolapsus rectal ?","a":"<p>Une <strong>rectocèle</strong> est le bombement du rectum à travers le vagin. Un <strong>prolapsus rectal</strong> correspond à l'extériorisation du rectum par l'anus.</p>"},{"i":"4a983152ecc6","n":44,"o":"44-12","u":"Définition","t":"Définir le prolapsus génital de la femme","q":"Quelle est la définition du prolapsus génital de la femme ?","a":"<p>Le prolapsus génital est une <strong>hernie des organes pelviens</strong> à travers le vagin, s'extériorisant par une <strong>tuméfaction vaginale</strong>.</p>"},{"i":"776a975d87d1","n":44,"o":"44-12","u":"Définition","t":"Définir le prolapsus génital de la femme","q":"Comment différencier un prolapsus génital d'une masse abdominale ?","a":"<p>Le prolapsus génital se manifeste par une tuméfaction vaginale et n'est <strong>pas palpable</strong> au niveau abdominal, contrairement par exemple à un fibrome utérin ou une masse annexielle.</p>"},{"i":"4402adf598c8","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Le prolapsus génital est-il habituellement douloureux ?","a":"<p>Non, le prolapsus génital n’est <strong>habituellement pas douloureux</strong>. La douleur est un signe négatif à éliminer dans le diagnostic du prolapsus.</p>"},{"i":"4990e5dbbe64","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Quels sont les signes fonctionnels digestifs et génito-sexuels pouvant être associés à un prolapsus génital ?","a":"<p>Les signes fonctionnels associés au prolapsus génital sont :</p><ul><li><strong>Digestifs (en cas de rectocèle)</strong> : faux besoins (pouvant entraîner une fausse diarrhée sur fécalome) et <strong>dyschésie</strong> (exonération difficile), nécessitant parfois des manœuvres digitales.</li><li><strong>Génito-sexuels</strong> : <strong>dyspareunie</strong> et sensation de <strong>béance vulvaire</strong>, pouvant conduire à l’arrêt de l’activité sexuelle.</li></ul>"},{"i":"6b40131ccc4a","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Quelles sont les manifestations urinaires pouvant être associées à un prolapsus génital ?","a":"<p>Les manifestations urinaires associées à un prolapsus peuvent inclure :</p><ul><li>Un <strong>syndrome d’hyperactivité vésicale</strong> (urgenturie, incontinence urinaire par urgence).</li><li>Des <strong>troubles de la vidange vésicale</strong> aux stades avancés (dysurie, résidu post-mictionnel, infections urinaires récidivantes, rétention aiguë d'urine), parfois nécessitant des manœuvres digitales de réintroduction.</li></ul><p>Ces troubles peuvent être liés à l'« <strong>effet pelote</strong> », une plicature ou compression de l'urètre lors de l'extériorisation du prolapsus, créant un obstacle sous-vésical.</p>"},{"i":"83c56f3582e2","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Quel est le symptôme principal du prolapsus génital ?","a":"<p>Le symptôme principal du prolapsus génital est une <strong>pesanteur pelvienne</strong> et une <strong>sensation de boule à la vulve</strong>. Ces symptômes sont augmentés à l’orthostatisme et en fin de journée.</p>"},{"i":"a5232121b5ec","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Comment rechercher une incontinence urinaire à l'effort (IUE) masquée lors de l'examen clinique d'un prolapsus ?","a":"<p>Pour rechercher une IUE masquée par le prolapsus, il faut réaliser un <strong>test d’effort de poussée abdominale et de toux</strong> avec la <strong>vessie pleine</strong>, après avoir <strong>réduit le prolapsus</strong>. L'IUE peut être masquée par la plicature ou la compression de l'urètre par le prolapsus lui-même.</p>"},{"i":"5cddeadf5bb1","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Outre la grossesse, le fibrome et le kyste ovarien, quelles sont les causes utérines de tuméfaction pelvienne chez la femme ?","a":"Les causes utérines incluent :\n<ul>\n<li>Le <strong>sarcome utérin</strong> / <strong>léiomyosarcome</strong> : rare, souvent après la ménopause, avec une masse à progression rapide.</li>\n<li>L'<strong>adénomyose</strong> : rarement, l'utérus ne dépasse généralement pas deux fois sa taille normale.</li>\n<li>Le <strong>cancer de l'endomètre</strong> : exceptionnellement, surtout si la tumeur est endocavitaire avec sténose du col, entraînant alors une hématométrie ± pyométrie.</li>\n</ul>"},{"i":"7e1ab343f861","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Outre la grossesse, le fibrome et le kyste ovarien, quelles sont les causes péritonéales et digestives pouvant provoquer une tuméfaction pelvienne chez la femme ?","a":"Les causes péritonéales et digestives incluent :\n<ul>\n<li><strong>Péritonéales</strong> : L'<strong>endométriose du cul-de-sac recto-utérin</strong>, qui se présente plus comme une induration ou un nodule qu'une véritable masse.</li>\n<li><strong>Digestives</strong> (rares) :\n<ul>\n<li>La <strong>sigmoïdite</strong>.</li>\n<li>Le <strong>cancer colorectal</strong>.</li>\n</ul>\n</li>\n</ul>"},{"i":"86adaa8aef0f","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Outre la grossesse, le fibrome et le kyste ovarien, quelles sont les causes ovariennes et tubaires de tuméfaction pelvienne chez la femme ?","a":"Les causes ovariennes et tubaires incluent :\n<ul>\n<li><strong>Ovariennes</strong> :\n<ul>\n<li>L'<strong>abcès ovarien</strong> (post-pelvipéritonite, post-ponction).</li>\n<li>L'<strong>endométriome</strong>.</li>\n<li>Le <strong>cancer de l'ovaire</strong> (rare avant la ménopause).</li>\n</ul>\n</li>\n<li><strong>Tubaires</strong> :\n<ul>\n<li>L'<strong>hydrosalpinx</strong>.</li>\n<li>Le <strong>bloc adhérentiel post-infectieux</strong>.</li>\n<li>Le <strong>kyste paratubaire / vestigial</strong> (la trompe se dilate rarement assez pour donner une masse importante, souvent masse annexielle infectieuse mixte trompe + ovaire).</li>\n</ul>\n</li>\n</ul>"},{"i":"c55083e4c5e1","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Quels sont les signes d'alerte (\"drapeau rouge\") pour envisager une tumeur maligne face à une tuméfaction pelvienne chez la femme ?","a":"Une masse pelvienne doit faire suspecter une tumeur maligne jusqu'à preuve du contraire si elle présente les caractéristiques suivantes :\n<ul>\n<li><strong>Irrégulière</strong>.</li>\n<li><strong>Fixée</strong>.</li>\n<li>À <strong>progression rapide</strong>.</li>\n<li>Surtout si elle survient <strong>après la ménopause</strong>.</li>\n<li>Ou en présence d'une <strong>ascite</strong>.</li>\n</ul>\nCela évoque particulièrement un cancer de l'ovaire, un sarcome ou un cancer de l'endomètre."},{"i":"0e9bf4dd0dd2","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quelles sont les manifestations et les complications du syndrome de masse pelvienne associé aux fibromes utérins ?","a":"<p>Le syndrome de masse pelvienne se caractérise par une <strong>pesanteur pelvienne</strong>, une masse abdominale palpable et une augmentation du volume de l'abdomen, d'apparition progressive et sans douleur vraie. Les complications résultent de la compression d'organes de voisinage :</p><ul><li><strong>Vésicales</strong> : pollakiurie, rétention d'urines.</li><li><strong>Urétrale</strong> : urétéro-hydronéphrose, coliques néphrétiques, pyélonéphrites.</li><li><strong>Digestives</strong> : constipation, faux besoins.</li><li><strong>Veineuses pelviennes</strong> : œdèmes des membres inférieurs, TVP.</li><li><strong>Nerveuses</strong> : sciatalgie, névralgie obturatrice.</li></ul><p>Les fibromes à risque de causer un syndrome de masse pelvienne sont ceux de <strong>grand volume (> 5 cm)</strong> et les <strong>fibromes sous-séreux</strong> (FIGO 5-7).</p>"},{"i":"1cb65f4d0961","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Dans quel contexte clinique les dysménorrhées peuvent-elles être associées à des fibromes utérins ?","a":"<p>Les dysménorrhées peuvent être associées à des fibromes utérins si le fibrome est situé au niveau du <strong>col</strong> ou de l'<strong>isthme</strong> (FIGO 8), car il peut gêner l'évacuation normale du flux menstruel.</p>"},{"i":"87c438d828fc","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quels sont les éléments clés de l'examen clinique au toucher vaginal (TV) en présence de fibromes utérins ?","a":"<p>Lors du toucher vaginal (TV), les éléments clés sont :</p><ul><li>Des <strong>fibromes palpables</strong> (souvent interstitiels ou sous-séreux).</li><li>Un <strong>utérus augmenté de volume</strong>, en cas de fibromes interstitiels ou sous-séreux.</li><li>Une <strong>masse latéro-utérine dépendante de l'utérus</strong> pour un fibrome sous-séreux sessile.</li><li>Une <strong>masse latéro-utérine indépendante</strong>, évoquant un fibrome pédiculé.</li></ul>"},{"i":"9c7588d339a5","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quels sont les principaux tableaux cliniques des fibromes utérins symptomatiques ?","a":"<p>Les fibromes utérins symptomatiques se manifestent principalement sous <strong>trois tableaux cliniques</strong> :</p><ul><li>Des <strong>saignements utérins anormaux</strong> (le signe le plus fréquent).</li><li>Un <strong>syndrome de masse pelvienne</strong>.</li><li>Des <strong>dysménorrhées</strong>.</li></ul>"},{"i":"edb5d4e12464","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Comment les saignements utérins anormaux liés aux fibromes utérins se manifestent-ils et quels fibromes sont le plus souvent en cause ?","a":"<p>Les saignements utérins anormaux se manifestent par :</p><ul><li>Des <strong>ménorragies</strong> (règles > 6 jours et/ou > 80 mL), souvent associées à une polyménorrhée.</li><li>Des <strong>métrorragies</strong> sont rares isolées, mais des <strong>ménométrorragies</strong> sont plus fréquentes.</li></ul><p>Une complication fréquente est l'<strong>anémie ferriprive</strong>. Les fibromes expliquant le plus souvent ces saignements sont les <strong>fibromes sous-muqueux</strong> (FIGO 0-2), suivis plus rarement par les fibromes interstitiels (FIGO 3-4).</p>"},{"i":"f66a4149b8ba","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quelle conduite à tenir est préconisée devant des ménométrorragies associées à un utérus polymyomateux palpable au TV ?","a":"<p>Devant des ménométrorragies et un utérus polymyomateux palpable au TV, il convient de :</p><ul><li>Doser la <strong>NFS et la ferritine</strong> (pour rechercher une anémie ferriprive).</li><li>Réaliser une <strong>échographie pelvienne</strong>.</li><li>Apprécier le <strong>score de Higham</strong> pour quantifier les ménorragies.</p></ul>"},{"i":"29ac962ba208","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Quelles sont les caractéristiques d'un kyste ovarien à l'examen clinique qui doivent faire craindre une malignité ou d'autres pathologies graves ?","a":"<p>Les caractéristiques d'un kyste ovarien devant faire craindre une <strong>malignité</strong> (cancer de l'ovaire) ou d'autres pathologies graves (endométriose, cause infectieuse) à l'examen clinique sont :</p><ul><li>Une masse <strong>irrégulière</strong>.</li><li>Une masse <strong>fixée</strong>.</li><li>La présence d'une <strong>ascite</strong> ou d'une <strong>hépatomégalie</strong> (recherchées lors de l'examen abdominal).</li></ul>"},{"i":"662021e267c4","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Quels symptômes un kyste ovarien volumineux peut-il entraîner ?","a":"<p>Un kyste ovarien volumineux peut entraîner ce qu'on appelle un <strong>syndrome de masse pelvienne</strong>, se manifestant par :</p><ul><li>Une sensation de <strong>pesanteur</strong> pelvienne.</li><li>Une <strong>augmentation du volume abdominal</strong>.</li><li>Des <strong>signes de compression</strong>, notamment vésicale (miction fréquente) ou digestive (constipation).</li></ul>"},{"i":"6efe0b5461d9","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Que doit faire évoquer une douleur pelvienne chez une patiente présentant un kyste ovarien ?","a":"<p>Une douleur pelvienne, en présence d'un kyste ovarien, doit faire évoquer une <strong>complication</strong> du kyste, telle qu'une <strong>torsion</strong> de l'ovaire, une <strong>hémorragie intra-kystique</strong> ou une <strong>rupture</strong> du kyste.</p>"},{"i":"79e8a6cba2b6","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Dans quelles circonstances un kyste ovarien est-il le plus fréquemment découvert ?","a":"<p>La découverte d'un kyste ovarien est le plus souvent <strong>fortuite</strong>, lors d'un examen clinique de routine ou d'une échographie abdomino-pelvienne.</p>"},{"i":"f15fff7a775c","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Quelles sont les caractéristiques principales d'un kyste ovarien bénin à l'examen clinique au toucher vaginal ?","a":"<p>À l'examen clinique, un kyste ovarien orientant vers la bénignité se présente classiquement comme une <strong>masse latéro-utérine</strong> qui est :</p><ul><li><strong>Indépendante de l'utérus</strong>, séparée par un sillon, et ne transmettant pas les mouvements utérins.</li><li>De consistance <strong>régulière</strong>.</li><li><strong>Mobile</strong>.</li></ul>"},{"i":"4ac3c6aa43d1","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Quelle est la conduite à tenir si un kyste ovarien présente des critères de malignité ou une zone solide à l'échographie ?","a":"<p>Si un kyste ovarien présente des critères de malignité (aucun critère de bénignité) ou une zone solide à l'échographie, il faut réaliser une <strong>IRM</strong>, éventuellement des marqueurs comme le <strong>CA-125</strong>, et envisager une <strong>cœlioscopie</strong>.</p>"},{"i":"c1b657d58d1a","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Quels sont les critères échographiques de bénignité à rechercher pour différencier un kyste ovarien fonctionnel d'un kyste organique ?","a":"<p>Les critères échographiques de bénignité doivent tous être présents :</p><ul><li>Image <strong>uniloculaire</strong> (ou cloison fine < 3 mm)</li><li><strong>Anéchogène</strong> pur, sans zone solide ni végétation</li><li><strong>Paroi fine</strong></li><li>Vascularisation périphérique régulière (index de résistance > 0,50)</li><li>Taille <strong>< 7 cm</strong></li><li>Absence d'ascite</li></ul>"},{"i":"cd81788cfdf7","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Comment l'évolution échographique à 3 mois permet-elle de différencier un kyste ovarien fonctionnel d'un kyste organique ?","a":"<ul><li>Un <strong>kyste fonctionnel</strong> est caractérisé par une <strong>régression</strong> à l'échographie de contrôle à 3 mois.</li><li>Un <strong>kyste organique</strong> est caractérisé par sa <strong>persistance</strong> au-delà de 3 mois.</li></ul>"},{"i":"edee98780bb9","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Quelle est la conduite à tenir initiale en présence de tous les critères échographiques de bénignité pour un kyste ovarien ?","a":"<p>En présence de tous les critères de bénignité, la conduite à tenir est une <strong>simple surveillance</strong> et une <strong>échographie de contrôle à 3 mois</strong> pour vérifier la régression du kyste (éliminer un kyste fonctionnel) et éviter une chirurgie d'emblée.</p>"}]};